def copiar_tarifas(apps, schema_editor):
    """Enmienda 4, RF-CAT-48: cada producto con categoría recibe su sistema, su código y una
    copia de todas las tarifas de la categoría con sus fechas. No se pierde ninguna."""
    Producto = apps.get_model("catalog", "Producto")
    IscTarifa = apps.get_model("catalog", "IscTarifa")
    ProductoIscTasa = apps.get_model("catalog", "ProductoIscTasa")
    for p in Producto.objects.filter(isc_categoria__isnull=False).select_related("isc_categoria"):
        categoria = p.isc_categoria
        Producto.objects.filter(pk=p.pk).update(
            isc_sistema=categoria.sistema, isc_codigo_tipo_sistema=categoria.codigo_tipo_sistema
        )
        ProductoIscTasa.objects.bulk_create(
            ProductoIscTasa(
                empresa_id=p.empresa_id,
                producto_id=p.pk,
                vigente_desde=t.vigente_desde,
                monto_por_litro=t.monto_por_litro,
                creado_por_id=t.creado_por_id,
            )
            for t in IscTarifa.objects.filter(categoria=categoria)
        )
    # Las FK diferidas de los datos convertidos se verifican ya: si no, PostgreSQL no deja
    # alterar las tablas en la misma transacción ("pending trigger events").
    schema_editor.execute("SET CONSTRAINTS ALL IMMEDIATE")


